-- Spots catalog: migrated from src/data/spots.ts (2026-07-26)
CREATE TABLE public.spots (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  slug text NOT NULL UNIQUE,
  title text NOT NULL,
  location text NOT NULL,
  country text NOT NULL,
  type text NOT NULL CHECK (type IN ('Freshwater','Saltwater','Fly Fishing')),
  species jsonb NOT NULL DEFAULT '[]',
  image_key text NOT NULL DEFAULT 'fishing-spot',
  featured boolean NOT NULL DEFAULT false,
  description text NOT NULL,
  coordinates jsonb NOT NULL,
  water_temperature jsonb NOT NULL,
  weather jsonb NOT NULL,
  tides jsonb NOT NULL,
  recommended_gear jsonb NOT NULL,
  best_times jsonb NOT NULL,
  difficulty text NOT NULL CHECK (difficulty IN ('Beginner','Intermediate','Advanced')),
  regulations jsonb NOT NULL DEFAULT '[]',
  sponsored boolean DEFAULT false,
  sponsored_url text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.spots ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public read spots" ON public.spots FOR SELECT TO anon, authenticated USING (true);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (1, 'sydney-harbour-kingfish', 'Sydney Harbour Kingfish', 'Sydney, NSW', 'AU', 'Saltwater', '["yellowtail kingfish","bream","flathead","tailor"]'::jsonb, 'fishing-spot', true, 'Australia''s most famous harbour doubles as a serious kingfish fishery. Work the markers, moorings and washes from a boat or kayak, or chase bream and flathead from the countless wharves and flats inside the harbour.', '{"lat":-33.8523,"lng":151.2108}'::jsonb, '{"current":17,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Partly Cloudy","temperature":63,"humidity":60,"windSpeed":10,"windDirection":"W"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["Medium-heavy spin rod (PE2-3)","Stickbaits and knife jigs","Live squid or yakkas","Fluorocarbon leader 40-60lb"],"optional":["Downrigger","Kayak or boat","Landing net","Polarized sunglasses"]}'::jsonb, '["Dawn tide changes","Early morning (5-9 AM)","Spring through autumn for kings"]'::jsonb, 'Intermediate', '["NSW Recreational Fishing Fee required (18+)","Kingfish minimum size and bag limits apply","Check current NSW DPI Fisheries rules"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (2, 'port-phillip-bay-snapper', 'Port Phillip Bay Snapper', 'Melbourne, VIC', 'AU', 'Saltwater', '["snapper","King George whiting","flathead","squid"]'::jsonb, 'duck-spot', false, 'Melbourne''s big bay fires from spring when snapper move in to spawn. Whiting, flathead and calamari keep the fishing going year-round, with launching ramps and land-based options right around the bay.', '{"lat":-38.09,"lng":144.85}'::jsonb, '{"current":12,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Overcast","temperature":55,"humidity":70,"windSpeed":12,"windDirection":"SW"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["7ft medium spin rod","Running sinker rigs","Fresh squid and pilchards","Berley"],"optional":["Sounder","Squid jigs","Rod holders","Drift anchor"]}'::jsonb, '["Snapper run (Oct-Dec)","Dawn and dusk","Light northerly mornings"]'::jsonb, 'Beginner', '["Victorian Recreational Fishing Licence required","Snapper size and bag limits apply","Check current VFA rules"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (3, 'cairns-black-marlin', 'Cairns Black Marlin Grounds', 'Cairns, QLD', 'AU', 'Saltwater', '["black marlin","Spanish mackerel","coral trout","yellowfin tuna"]'::jsonb, 'fishing-spot', true, 'The waters off Cairns are the world''s premier heavy-tackle black marlin fishery, with giants over 1,000lb taken each season along the reef edge. Inside the reef, coral trout and mackerel offer outstanding sport fishing.', '{"lat":-16.75,"lng":146.1}'::jsonb, '{"current":24,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Sunny","temperature":79,"humidity":65,"windSpeed":15,"windDirection":"SE"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["Heavy trolling outfit (37-60kg)","Skirted lures and rigged baits","Fighting harness","Reef-safe sunscreen"],"optional":["Charter booking","Outriggers","Camera","Seasickness tablets"]}'::jsonb, '["Heavy tackle season (Sept-Dec)","Reef fishing year-round","Neap tides for reef species"]'::jsonb, 'Advanced', '["No general QLD licence for tidal waters","GBR Marine Park zoning applies — check zones","Coral reef fin fish size/bag limits and closures apply"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (4, 'darwin-harbour-barramundi', 'Darwin Harbour Barramundi', 'Darwin, NT', 'AU', 'Saltwater', '["barramundi","threadfin salmon","mangrove jack","queenfish"]'::jsonb, 'duck-spot', true, 'Barra fishing on Darwin''s doorstep. Work the creek mouths, rock bars and flats of the harbour arms for barramundi and threadfin, with the famous run-off season producing the Territory''s best metre-plus fish.', '{"lat":-12.47,"lng":130.83}'::jsonb, '{"current":26,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Sunny","temperature":86,"humidity":55,"windSpeed":8,"windDirection":"E"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["Baitcast or spin combo (30-50lb braid)","Hardbody lures 90-120mm","Soft vibes","Heavy mono leader 60-80lb"],"optional":["Boat or guided charter","Cast net for live bait","Sounder with side scan"]}'::jsonb, '["Run-off (Feb-Apr)","Build-up (Oct-Dec)","Making tides around creek mouths"]'::jsonb, 'Intermediate', '["No recreational fishing licence required in NT","Barramundi size and possession limits apply","Check NT Fisheries rules and closed areas"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (5, 'exmouth-ningaloo-flats', 'Exmouth & Ningaloo Flats', 'Exmouth, WA', 'AU', 'Saltwater', '["bonefish","giant trevally","queenfish","golden trevally"]'::jsonb, 'fishing-spot', false, 'World-class sight fishing on the flats inside Ningaloo Reef. Stalk bonefish, permit and cruising trevally in ankle-deep water, or head outside the reef for serious bluewater action.', '{"lat":-21.93,"lng":114.12}'::jsonb, '{"current":23,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Clear","temperature":77,"humidity":45,"windSpeed":14,"windDirection":"SE"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["8-10 weight fly rod or 4000-size spin","Crab and shrimp flies","Flats booties","Polarized sunglasses"],"optional":["Guide booking","Sun gloves and buff","Stripping basket"]}'::jsonb, '["Morning low light with sun overhead by 9 AM","Neap tides for the flats","March-June prime"]'::jsonb, 'Advanced', '["WA licence required only for boat-based fishing","Ningaloo Marine Park sanctuary zones — no fishing zones apply","Check current WA DPIRD rules"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (6, 'great-lake-tasmania-trout', 'Great Lake Highland Trout', 'Central Highlands, TAS', 'AU', 'Fly Fishing', '["brown trout","rainbow trout"]'::jsonb, 'duck-spot', false, 'Tasmania''s Central Highlands hold some of the world''s best wild brown trout water. Great Lake and the surrounding lakes offer polaroiding, tailing fish in the shallows, and classic loch-style fishing.', '{"lat":-41.87,"lng":146.68}'::jsonb, '{"current":7,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Windy","temperature":43,"humidity":75,"windSpeed":18,"windDirection":"NW"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["6-weight fly rod","Wet flies and nymphs","Waders","Warm layered clothing"],"optional":["Drift boat hire","Polaroiding sunglasses","Landing net"]}'::jsonb, '["Early season wets (Aug-Oct)","Summer polaroiding (Dec-Feb)","Overcast days for loch-style"]'::jsonb, 'Intermediate', '["Tasmanian Inland Fisheries licence required","Season and method rules vary by water — check IFS","Bag and size limits apply"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (7, 'murray-river-cod-yarrawonga', 'Murray River Cod Country', 'Yarrawonga, VIC/NSW', 'AU', 'Freshwater', '["Murray cod","golden perch"]'::jsonb, 'fishing-spot', true, 'The stretch of the Murray below Yarrawonga Weir is legendary Murray cod water. Cast big hardbodies and surface lures around snags and undercut banks for Australia''s largest freshwater fish.', '{"lat":-36.02,"lng":146}'::jsonb, '{"current":11,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Foggy Morning","temperature":48,"humidity":85,"windSpeed":5,"windDirection":"S"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["Heavy baitcast combo (50lb braid)","Large hardbodies and spinnerbaits","Surface lures for dawn/dusk","Heavy leader 60-80lb"],"optional":["Kayak or boat","Large landing net","Lip grips with scales"]}'::jsonb, '["Cod opening (Dec 1)","Surface bite on summer evenings","Autumn stability"]'::jsonb, 'Intermediate', '["NSW or VIC licence required depending on bank","Murray cod closed season Sep 1 - Nov 30","Slot limit applies to Murray cod — check current rules"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (8, 'coorong-mulloway-surf', 'Coorong Surf Mulloway', 'Coorong, SA', 'AU', 'Saltwater', '["mulloway","Australian salmon","bream","flathead"]'::jsonb, 'duck-spot', false, 'The wild surf beaches of the Coorong and Murray Mouth are South Australia''s premier land-based mulloway fishery. Long beaches, big gutters, and the chance of a genuine metre-plus fish from the sand.', '{"lat":-35.55,"lng":138.88}'::jsonb, '{"current":13,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Partly Cloudy","temperature":57,"humidity":65,"windSpeed":16,"windDirection":"SW"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["12-13ft surf rod","Star or grapnel sinkers","Fresh mullet or salmon fillet baits","Beach rod holder"],"optional":["4WD beach access permit","Headlamp for night sessions","Bait pump for cockles"]}'::jsonb, '["Night tides","After onshore blows","Autumn and spring runs"]'::jsonb, 'Intermediate', '["No general SA fishing licence required","Mulloway size and bag limits apply","Coorong National Park access rules — check before driving the beach"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (9, 'lake-jindabyne-trout', 'Lake Jindabyne Trout', 'Snowy Mountains, NSW', 'AU', 'Freshwater', '["brown trout","rainbow trout","Atlantic salmon"]'::jsonb, 'fishing-spot', false, 'A big, cold Snowy Mountains lake stocked with browns, rainbows and Atlantic salmon. Troll the drop-offs, fish bait from the bank, or fly fish the edges on dark for cruising browns.', '{"lat":-36.42,"lng":148.62}'::jsonb, '{"current":8,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Cold and Clear","temperature":39,"humidity":60,"windSpeed":9,"windDirection":"W"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["Light spin or 5-6wt fly rod","Tasmanian Devil lures","PowerBait or scrub worms","Warm clothing"],"optional":["Boat or kayak","Lead core trolling line","Landing net"]}'::jsonb, '["Dawn and dusk","Evening rise in summer","Winter for lake browns"]'::jsonb, 'Beginner', '["NSW Recreational Fishing Fee required","Trout bag and size limits apply","Rivers upstream have seasonal closures — check NSW DPI"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (10, 'hervey-bay-golden-trevally', 'Hervey Bay Flats & Bay', 'Hervey Bay, QLD', 'AU', 'Saltwater', '["golden trevally","longtail tuna","whiting","flathead"]'::jsonb, 'duck-spot', false, 'Sheltered by K''gari (Fraser Island), Hervey Bay offers calm-water sight fishing for golden trevally on the flats, longtail tuna busting bait in the bay, and easy family fishing options year-round.', '{"lat":-25.29,"lng":152.84}'::jsonb, '{"current":20,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Sunny","temperature":72,"humidity":55,"windSpeed":11,"windDirection":"SE"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["3000-4000 spin combo","Soft plastics and metal slugs","Yabby pump","Light fluorocarbon leader"],"optional":["Flats skiff or kayak","8-weight fly rod","Polarized sunglasses"]}'::jsonb, '["Making tide on the flats","Tuna season (Aug-Nov)","Winter whiting (May-Aug)"]'::jsonb, 'Beginner', '["No general QLD licence for tidal waters","Great Sandy Marine Park zoning applies","Size and bag limits — check QLD DAF rules"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (11, 'somerset-dam-bass', 'Somerset Dam Bass', 'Somerset Region, QLD', 'AU', 'Freshwater', '["Australian bass","golden perch","saratoga"]'::jsonb, 'fishing-spot', false, 'One of Queensland''s premier stocked impoundments, famous for schooled Australian bass in open water. Sound up the schools and drop soft vibes or blades for hot mid-water action.', '{"lat":-27.12,"lng":152.55}'::jsonb, '{"current":16,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Clear","temperature":66,"humidity":50,"windSpeed":7,"windDirection":"SW"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["Light spin combo (10-15lb braid)","Soft vibes and blades","Sounder","Tail spinners"],"optional":["Electric motor","Kayak","Trolling hardbodies"]}'::jsonb, '["Schooled fish (autumn-winter)","Dawn topwater in summer","Stable weather patterns"]'::jsonb, 'Beginner', '["Stocked Impoundment Permit (SIPS) required to fish the dam","Bass closed season does not apply in impoundments","Check QLD DAF rules"]'::jsonb);
INSERT INTO public.spots (id, slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES (12, 'albany-king-george-sound', 'Albany & King George Sound', 'Albany, WA', 'AU', 'Saltwater', '["King George whiting","Australian salmon","snapper","squid"]'::jsonb, 'duck-spot', false, 'WA''s rugged south coast at its best. Chase big King George whiting and squid in the protected sound, or fish the surf beaches when the famous autumn salmon run pushes schools along the coast.', '{"lat":-35.03,"lng":117.92}'::jsonb, '{"current":16,"unit":"°C","trend":"stable"}'::jsonb, '{"condition":"Showers","temperature":59,"humidity":75,"windSpeed":20,"windDirection":"SW"}'::jsonb, '{"nextHigh":"N/A","nextLow":"N/A","current":"slack"}'::jsonb, '{"essential":["Light spin combo for whiting","Surf rod for salmon runs","Squid jigs","Fresh squid and worm baits"],"optional":["Boat for the sound","Waders","Rock fishing safety gear (lifejacket)"]}'::jsonb, '["Autumn salmon run (Mar-May)","Calm mornings in the sound","Squid on light winds"]'::jsonb, 'Beginner', '["WA licence required only for boat-based fishing","Rock fishing safety rules — lifejackets recommended","Check current WA DPIRD size and bag limits"]'::jsonb);SELECT setval(pg_get_serial_sequence('public.spots','id'), (SELECT max(id) FROM public.spots));
ALTER TABLE public.spot_reviews ADD CONSTRAINT spot_reviews_spot_id_fkey FOREIGN KEY (spot_id) REFERENCES public.spots(id) ON DELETE CASCADE;
